  const box=el('div'),status=el('p'),upload=el('input'),label=el('label','导入本项目准确底稿原包（ZIP）'),choose=el('select'),previous=btn('上一张表'),next=btn('下一张表'),save=btn('保存本表填写'),original=btn('下载9200原件'),refresh=btn('刷新9200'),info=el('p'),area=el('div'),toolbar=el('div');box.className='rw-inline-tb';status.setAttribute('role','status');upload.type='file';upload.accept='.zip';upload.multiple=true;upload.id='report-tb-import';label.append(upload);choose.id='report-tb-workbook';choose.setAttribute('aria-label','9200原工作簿版本');previous.id='report-tb-previous';next.id='report-tb-next';save.id='report-tb-save';info.id='report-tb-sheet-page';toolbar.className='rw-tb-toolbar';toolbar.append(choose,previous,next,save,original,refresh);box.append(label,status,toolbar,info,area);host.append(box);
