  save.onclick=async()=>{if(busy||!current)return;const ticket=serial,projectId=key,file=current;lock(true);try{const fresh=await S.get(projectId);if(!alive(ticket))return;if(fresh.rev!==record.rev)throw Error('本项目已被其他页面更新，请先备份未保存填写并刷新；未覆盖。');await L.fileFor({path:file.name,sha256:file.sha256},await L.prepare(fresh));if(!alive(ticket))return;const result=await S.save(projectId,record.rev,{...provenancePatch,answers:{...(record.answers||{}),[file.sha256]:structuredClone(edits)}});if(!alive(ticket))return;record=result;provenancePatch={};dirty=false;save.textContent='保存本表填写';say('9200填写已保存；原件、公式与链接未改变。');}catch(e){if(alive(ticket))say(e.message,true);}finally{if(alive(ticket)){lock(false);if(model)draw();}}};
